6	/**
7	 * Normalizes an owner's {@code address} to its canonical form (trimmed, whitespace collapsed,
8	 * upper-cased, abbreviations expanded) in place on the shared body, so the persisted and
9	 * returned address is that canonical string and every later address comparison sees it. It
10	 * runs before validation, so an address that is blank once normalized is rejected there as a
11	 * missing required field. It mutates the already-published body variable rather than binding
12	 * {@code @RequestBody}, so it composes after the sole binding step in the pipeline.
13	 */
14	public class NormalizeOwnerAddress {
15	
16	    public void service(@Val OwnerFieldsDto request) {
17	        String address = request.getAddress();
18	        if (address == null) {
19	            return; // absence is reported by the required-field check
20	        }
21	        request.setAddress(OwnerAddress.normalize(address));
22	    }
23	}
