19	    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerFieldsException {
20	        String postcode = request.getPostcode();
21	        if (postcode == null || postcode.isBlank()) {
22	            return; // optional when absent
23	        }
24	        if (!PostcodeRange.isValidForCity(request.getCity(), postcode)) {
25	            throw new InvalidOwnerFieldsException(List.of("postcode"));
26	        }
27	    }
