1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
8	
9	/**
10	 * Runs in {@code POST /api/owners} after {@link ValidateOwnerFields}, reading the
11	 * already-normalized body as a variable. Consolidates the former separate telephone, email and
12	 * household duplicate checks into one: it derives the request's
13	 * {@link OwnerIdentity#key identity key} and rejects the request with a 409 only when that
14	 * <em>whole</em> key equals an existing owner's, before any entity is built or persisted.
15	 *
16	 * <p>Because the telephone is part of the key, two members of one household (same household id)
17	 * with different telephones have different keys and are both allowed; only an exact full-key
18	 * match is a duplicate. Reads the same transaction as the writes.
19	 */
20	public class EnsureUniqueOwnerIdentity {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DuplicateOwnerIdentityException {
24	
25	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(),
26	                requestHouseholdId(request));
27	
28	        for (Owner existing : ownerRepository.findAll()) {
29	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
30	                    existing.getHouseholdId());
31	            if (identityKey.equals(existingKey)) {
32	                throw new DuplicateOwnerIdentityException(identityKey);
33	            }
34	        }
35	    }
36	
37	    /**
38	     * The household id the request's owner will be assigned: the stable
39	     * {@link Household#id(String, String) household id} for its lastName and address when it
40	     * opts into a shared household, otherwise none (so a solo owner contributes no household
41	     * component to its key).
42	     */
43	    private static String requestHouseholdId(OwnerFieldsDto request) {
44	        return Boolean.TRUE.equals(request.getSharesHousehold())
45	                ? Household.id(request.getLastName(), request.getAddress()) : null;
46	    }
47	}
