3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs in {@code POST /api/owners} after the owner's household id has been assigned and before
9	 * it is saved, within the create transaction. Records on the built owner how many members its
10	 * household holds once this create completes: the owners already sharing the same
11	 * {@link Owner#getHouseholdId() household id} plus the new owner itself. Because the new owner
12	 * has not yet been persisted, {@link OwnerRepository#findAll()} returns only the existing
13	 * members, so the {@code + 1} accounts for the owner being created. An owner not joining a
14	 * household (no household id) counts as a household of one.
15	 */
16	public class AssignOwnerHouseholdSize {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = owner.getHouseholdId();
20	        long members = 1; // the owner being created, not yet persisted
21	        if (householdId != null) {
22	            members += ownerRepository.findAll().stream()
23	                    .filter(existing -> householdId.equals(existing.getHouseholdId()))
24	                    .count();
25	        }
26	        owner.setHouseholdSize((int) members);
27	    }
28	}
