3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs in {@code POST /api/owners} after the owner entity is built and before it is saved,
9	 * within the create transaction. Records on the built owner how many existing owners already
10	 * shared its firstName and lastName (compared case-insensitively) at the moment of creation.
11	 * Because the new owner has not yet been persisted, {@link OwnerRepository#findAll()} returns
12	 * only the owners that existed before this create, so the count excludes the owner itself.
13	 */
14	public class AssignOwnerNamesakeCount {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        long count = ownerRepository.findAll().stream()
18	                .filter(existing -> isNamesake(owner, existing))
19	                .count();
20	        owner.setNamesakeCount((int) count);
21	    }
22	
23	    /** Whether the two owners share the same first and last name, ignoring case. */
24	    private static boolean isNamesake(Owner a, Owner b) {
25	        return a.getFirstName().equalsIgnoreCase(b.getFirstName())
26	                && a.getLastName().equalsIgnoreCase(b.getLastName());
27	    }
28	}
