1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Runs in {@code POST /api/owners} after the owner's namesake count has been recorded and before
8	 * it is saved, within the create transaction. Records on the built owner its numeric membership
9	 * level assigned at creation: it starts at 1, gains 1 when an email is present and 1 more when
10	 * {@link Owner#getNamesakeCount() namesakeCount} is 0, capped at 3 (level 4 is reserved for
11	 * tenure). Runs after {@link AssignOwnerNamesakeCount} so the count it reads is final.
12	 */
13	public class AssignOwnerMembershipLevel {
14	
15	    /** The highest level assignable at creation; level 4 is reserved for tenure. */
16	    private static final int MAX_LEVEL = 3;
17	
18	    public void service(@Val Owner owner) {
19	        int level = 1;
20	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
21	        if (hasEmail) {
22	            level++;
23	        }
24	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
25	        if (unique) {
26	            level++;
27	        }
28	        owner.setMembershipLevel(Math.min(level, MAX_LEVEL));
29	    }
30	}
