20	    static final int BULK_SIGNUP_THRESHOLD = 80;
21	
22	    public void service(@Val Owner owner, @Val LocalDate registrationDate,
23	            OwnerRepository ownerRepository) {
24	        long dayCount = ownerRepository.countRegisteredOn(registrationDate);
25	        owner.setBulkSignupWarning(dayCount > BULK_SIGNUP_THRESHOLD);
26	    }
