3	import java.util.Comparator;
4	import java.util.List;
5	import java.util.Map;
6	import java.util.Optional;
7	
8	/**
9	 * Telephone normalization shared by the owner pipelines: converts a supplied telephone to
10	 * canonical E.164 form (a leading {@code +}, country code, then national digits), so an
11	 * owner's telephone is stored, returned and compared in one representation.
12	 */
13	public final class OwnerTelephone {
14	
15	    /** Country code assumed when the input carries no explicit {@code +} prefix. */
16	    private static final String DEFAULT_COUNTRY_CODE = "61";
17	
18	    /**
19	     * National-number digit count required per country code. The national number (the digits
20	     * after the country code) must be exactly this long for the number to be valid, e.g.
21	     * {@code +61} takes 9 national digits and {@code +1} takes 10.
22	     */
23	    private static final Map<String, Integer> NATIONAL_DIGITS = Map.of("1", 10, "61", 9);
24	
25	    /** Known country codes, longest first, so the longest matching prefix wins. */
26	    private static final List<String> COUNTRY_CODES = NATIONAL_DIGITS.keySet().stream()
27	            .sorted(Comparator.comparingInt(String::length).reversed())
28	            .toList();
29	
30	    /** E.164 allows between 8 and 15 digits after the {@code +} for other country codes. */
31	    private static final int MIN_DIGITS = 8;
32	    private static final int MAX_DIGITS = 15;
33	
34	    private OwnerTelephone() {
35	    }
36	
37	    /**
38	     * The E.164 form of {@code telephone}, or {@link Optional#empty()} when it cannot form a
39	     * valid E.164 number. Spaces, dashes and brackets are stripped. A leading {@code +} keeps
40	     * the given country code; otherwise country code {@code +61} is assumed and a single
41	     * leading {@code 0} is dropped from the national digits. For a recognised country code the
42	     * national number must have exactly the length that code requires ({@code +61} → 9,
43	     * {@code +1} → 10); otherwise the full number must carry 8 to 15 digits after the {@code +}.
44	     */
45	    public static Optional<String> toE164(String telephone) {
46	        if (telephone == null) {
47	            return Optional.empty();
48	        }
49	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
50	        String digits;
51	        if (cleaned.startsWith("+")) {
52	            digits = cleaned.substring(1);
53	        }
54	        else {
55	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
56	            digits = DEFAULT_COUNTRY_CODE + national;
57	        }
58	        if (!digits.matches("[0-9]+") || !hasValidLength(digits)) {
59	            return Optional.empty();
60	        }
61	        return Optional.of("+" + digits);
62	    }
63	
64	    /**
65	     * Whether the country-code-plus-national {@code digits} has an acceptable length: a
66	     * recognised country code fixes the national-number length, otherwise the whole number
67	     * must sit within the generic E.164 range.
68	     */
69	    private static boolean hasValidLength(String digits) {
70	        for (String code : COUNTRY_CODES) {
71	            if (digits.startsWith(code)) {
72	                int nationalLength = digits.length() - code.length();
73	                return nationalLength == NATIONAL_DIGITS.get(code);
74	            }
75	        }
76	        return digits.length() >= MIN_DIGITS && digits.length() <= MAX_DIGITS;
77	    }
78	}
