6	/**
7	 * Email normalization shared by the owner pipelines: decides whether an address is
8	 * syntactically valid and produces its canonical (lower-cased) form, so an owner's
9	 * email is validated and stored in one consistent representation.
10	 */
11	public final class OwnerEmail {
12	
13	    /** A syntactically valid address: {@code local@domain.tld} with no whitespace. */
14	    private static final Pattern VALID = Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
15	
16	    private OwnerEmail() {
17	    }
18	
19	    /** Whether {@code email} is a syntactically valid address. */
20	    public static boolean isValid(String email) {
21	        return email != null && VALID.matcher(email).matches();
22	    }
23	
24	    /** The canonical, lower-cased form of {@code email}. */
25	    public static String normalize(String email) {
26	        return email.toLowerCase(Locale.ROOT);
27	    }
28	}
